s=s.replace('<div className="flex items-center gap-1"><Button variant="outline" size="sm" onClick={() => { setZoom((value) => Math.max(1, value - 1)); setWindowStart(0); }} aria-label="Zoom out trend chart">−</Button><span', '<div className="flex items-center gap-1"><Button variant="outline" size="sm" onClick={() => { const nextZoom = Math.max(1, zoom - 1); setZoom(nextZoom); setWindowStart(0); setAnnouncement(`Zoom ${nextZoom} times. Showing chart window 1 of ${maxStart + 1}.`); }} aria-label="Zoom out trend chart">−</Button><span', 1)
